// AUTO-GENERATED by tools/director.py — do not hand-edit.
// blocking.js — one place that knows how a character acts, so no shot invents its own version.
import { E, V, ease, prog, clamp, lerp, shade, alpha, wordTime, talkAmount } from '/engine/core.js';
import { drawFigure, pose, posesAt, walkPose, blendPose } from '/engine/rig2d.js';
import { drawInkBean } from '/chars/inkbean.js';
import { PRESETS, mixFaces } from '/chars/acting.js';
import { CAST } from './cast.js';

// character rig: 'stick' = rig2d stick figures, 'inkbean' = the hand-drawn ink-bean rig
export const INKBEAN = true;

export const outfitOf = (who) => CAST[who] || Object.values(CAST)[0] || {};

export function person(g, who, o) {
  const outfit = o.outfit || outfitOf(who);
  return INKBEAN ? drawInkBean(g, { ...o, outfit }) : drawFigure(g, { ...o, outfit });
}

// Continuous expression: two presets blended across a window, never a hard cut.
// rig2d faces are discrete presets; the ink-bean rig takes continuous values.
export function faceAt(t, at, a, b, w = 0.22) {
  const A = PRESETS[a] || PRESETS.neutral;
  if (!b || at == null) return { ...A, look: (A.look || [0, 0]).slice() };
  const B = PRESETS[b] || A;
  // 65% of the blend happens AFTER `at`. A centred window makes the face change
  // before the word is spoken, which reads as an anticipatory flinch, not a reaction.
  return mixFaces(A, B, ease.inOut(prog(t, at - w * 0.35, at + w * 0.65)));
}

// Mouth amount for a line occupying [from,to] in SHOT-local time.
// talkAmount is keyed on GLOBAL time, so passing shot-local numbers straight
// through would silently mute every shot after the first.
export function speak(info, t, from = 0.05, to = 1e9) {
  const g0 = info.globalT - t;
  return talkAmount(info.globalT, g0 + from, g0 + to);
}

// A blink is 0.10 s. Blinking exactly on an expression change hides the jump
// between two discrete face presets — the oldest trick in 2D animation.
export const BLINK = 0.10;
export function blinkAt(t, at, mid) {
  if (at != null && Math.abs(t - at) < BLINK * 0.5) return 1;
  if (mid != null && Math.abs(t - mid) < BLINK * 0.5) return 1;
  return 0;
}

// Discrete expression presets, switched on a blink. Returns `a` before `at`.
export function exprAt(t, at, a, b) {
  if (!b || at == null) return a;
  return t >= at ? b : a;
}

// A beat anchored to a SPOKEN WORD, returned in SHOT-local seconds.
// wordTime() searches GLOBAL word timings, so the search must be anchored to this
// shot's start — an unanchored "me" would match the same word in an earlier shot
// and fire the beat at a negative time. Returns null when the word is absent or
// resolves outside this shot, so the caller falls back deliberately, not silently.
export function wordAt(info, word) {
  if (!word) return null;
  const s0 = (info.shot && info.shot.start) || 0;
  const g = wordTime(word, s0);
  if (g == null) return null;
  const local = g - s0, dur = info.dur || 0;
  if (dur && (local < -0.02 || local > dur + 0.02)) return null;
  return local;
}

// Pose for this frame, optionally with a gesture that LANDS ON a word.
// posesAt() already blends between keyframes, so a gesture is just a second key —
// this exposes the engine's own sequencer instead of inventing a second one.
export function poseAt(t, base, gAt, gPose, blend = 0.28) {
  if (gAt == null || !gPose) return pose(base);
  return posesAt(t, [[0, base], [gAt, gPose]], blend);
}

// A walk that does not skate.
// walkPose()'s planted foot travels 2*stride backwards per PI of phase, so the
// phase MUST be driven by DISTANCE TRAVELLED, not by elapsed seconds. Drive it
// with time and the feet slide the moment the shot is retimed — and every shot
// here is retimed to its measured line. u0/u1 are fractions of the shot, so the
// walk survives that retime.
export function walkAt(t, w, D, s, base) {
  if (!w) return null;
  const t0 = (w.u0 ?? 0) * D, t1 = (w.u1 ?? 1) * D;
  const span = Math.max(0.001, t1 - t0);
  const from = w.from ?? 0.5, to = w.to ?? 0.5, dx = to - from;
  const distLocal = Math.abs(dx) * E.W / Math.max(0.001, s);
  const phaseTotal = Math.PI * distLocal / (2 * (w.stride || 26));
  const k = clamp((t - t0) / span);
  const wp = walkPose(phaseTotal * k, w);
  // ease in and out so the first/last frame is not a jump between two poses
  const fade = Math.min(ease.inOut(clamp((t - t0) / 0.18)),
                        ease.inOut(clamp((t1 - t) / 0.18)));
  return {
    x: lerp(from, to, k),
    facing: w.facing || (dx < 0 ? -1 : 1),
    pose: fade >= 1 ? wp : blendPose(pose(base || 'stand'), wp, Math.max(0, fade)),
  };
}

// A prop held in a hand.
// The hand point is read from the SAME pose object the figure was drawn with, so
// the prop cannot drift from the hand during a walk or a gesture — no second copy
// of the pose to fall out of sync.
export function holdProp(g, spec, o) {
  if (!spec) return;

  // WORN, not held. A bag hangs on the torso: a strap over one shoulder and the
  // body at the opposite hip. It must not follow the hand, so it ignores the pose
  // entirely — only the facing and the figure scale matter.
  if (spec.worn) {
    const s = o.s || 1, f = o.facing || 1, k = s * (spec.scale || 1);
    const cx = o.x, base = o.y;
    const col = spec.color || '#6b4a35';
    g.save();
    // strap: shoulder (top, near side) down to the far hip
    g.strokeStyle = shade(col, -0.25); g.lineWidth = 8 * k; g.lineCap = 'round';
    g.beginPath();
    g.moveTo(cx - f * 20 * k, base - 178 * k);   // shoulder, not the skull (head centre is -208)
    g.lineTo(cx + f * 26 * k, base - 96 * k);
    g.stroke();
    // bag body at the hip
    const bw = 44 * k, bh = 34 * k, bx = cx + f * 30 * k, by = base - 84 * k;
    g.fillStyle = col;
    g.beginPath(); g.rect(bx - bw / 2, by - bh / 2, bw, bh); g.fill();
    g.strokeStyle = 'rgba(8,8,12,.85)'; g.lineWidth = 2.6 * k; g.stroke();
    g.fillStyle = alpha('#000000', 0.18);
    g.fillRect(bx - bw / 2, by - bh / 2, bw, bh * 0.30);
    g.restore();
    return;
  }

  const kind = spec.kind || 'mug';
  const po = o.pose || pose('stand');
  const h = po[spec.hand === 'back' ? 'hB' : 'hF'] || [0, -100];
  const f = o.facing || 1, s = o.s || 1, k = s * (spec.scale || 1);
  // Offset outward along the facing direction. A prop drawn dead-centre on the
  // hand covers the mitten and the limb appears to end in an object — the same
  // failure that made a `cheer` gesture look like the hand had vanished.
  const x = o.x + h[0] * f * s + f * 18 * k;
  const y = o.y + h[1] * s - 2 * k;
  const ink = 'rgba(8,8,12,.85)';
  g.save();
  g.translate(x, y);
  g.rotate((spec.tilt || 0) * f);
  if (kind === 'mug') {
    const w = 18 * k, hh = 22 * k;
    g.fillStyle = spec.color || '#efe7d8';
    g.beginPath(); g.rect(-w / 2, -hh / 2, w, hh); g.fill();
    g.strokeStyle = ink; g.lineWidth = 2.6 * k; g.stroke();
    g.beginPath(); g.arc(w / 2, 0, 6.5 * k, -Math.PI / 2, Math.PI / 2);
    g.lineWidth = 3.2 * k; g.stroke();
    g.fillStyle = 'rgba(255,255,255,.20)';
    g.fillRect(-w / 2, -hh / 2, w, 4 * k);
  } else if (kind === 'book') {
    const w = 24 * k, hh = 17 * k;
    g.fillStyle = spec.color || '#b8452f';
    g.beginPath(); g.rect(-w / 2, -hh / 2, w, hh); g.fill();
    g.strokeStyle = ink; g.lineWidth = 2.4 * k; g.stroke();
    g.fillStyle = 'rgba(245,240,228,.9)';
    g.fillRect(-w / 2 + 2.5 * k, -hh / 2 + 2.5 * k, w - 5 * k, hh - 5 * k);
  } else if (kind === 'phone') {
    const w = 12 * k, hh = 21 * k;
    g.fillStyle = '#15161d';
    g.beginPath(); g.rect(-w / 2, -hh / 2, w, hh); g.fill();
    g.strokeStyle = ink; g.lineWidth = 2.2 * k; g.stroke();
    g.fillStyle = spec.color || 'rgba(150,200,255,.85)';
    g.fillRect(-w / 2 + 2 * k, -hh / 2 + 2.5 * k, w - 4 * k, hh - 5 * k);
  } else {
    // Unknown kind: draw something WRONG on purpose. A prop that silently draws
    // nothing is invisible in review; a magenta box is not.
    const w = 16 * k, hh = 16 * k;
    g.fillStyle = '#ff00aa';
    g.beginPath(); g.rect(-w / 2, -hh / 2, w, hh); g.fill();
  }
  g.restore();
}

// Vertical: a 1080x1920 frame has 78% more height than 1920x1080, so landscape
// scales make a head unreadably small on a phone. These restore it.
export const S_WIDE = () => V(1.45, 2.20);
export const S_MED = () => V(1.75, 2.70);
export const S_CLOSE = () => V(2.6, 3.15);
